pub(crate) fn prepare_remote_text_update(&self) -> Option<RemoteTextPreparation> {
    if !self.local_lowering.get() || self.doc.holds_pending_update() {
        return None;
    }
    let before = self.doc_epoch();
    let (generation, env) = {
        let render = self.render.borrow();
        let lowered = render.stories.get("body")?;
        if lowered.doc_epoch != before || lowered.media != self.doc.media_sources()
            || !lowered.local.matches_source(&self.doc) {
            return None;
        }
        (lowered.generation, lowered.env.clone())
    };
    Some(RemoteTextPreparation {
        before, doc_before: self.doc.committed_epoch(), generation, env,
        length: self.doc.story_len("body").ok()?,
        measurement_patch: self.measurement_patch().take(),
    })
}

#[cfg(feature = "wasm")]
pub(crate) fn cancel_remote_text_update(&self) {
    self.typing_epoch.set(None);
    self.typing_preserves_seeds.set(false);
    if let Some(lowered) = self.render.borrow_mut().stories.get_mut("body") {
        lowered.local.edit = None;
        lowered.preview_edit = None;
        lowered.preview_paragraph_edits.clear();
    }
}

#[cfg(feature = "wasm")]
pub(crate) fn record_remote_text_update(&self, prepared: Option<RemoteTextPreparation>,
    proof: &crate::mutation_proof::Proof) -> bool {
