        self.cancel_remote_text_update();
        return false;
    };
    let units = candidate.text.encode_utf16().count() as u32;
    let valid = candidate.before_epoch == prepared.doc_before
        && candidate.after_epoch == self.doc.committed_epoch()
        && self.doc_epoch() == prepared.before.wrapping_add(1)
        && prepared.length.checked_add(units) == self.doc.story_len("body").ok()
        && self.render.borrow().stories.get("body").is_some_and(|lowered| {
            lowered.doc_epoch == prepared.before && lowered.generation == prepared.generation
                && lowered.env == prepared.env && lowered.media == self.doc.media_sources()
                && lowered.local.matches_source(&self.doc)
        });
    if !valid {
        self.cancel_remote_text_update();
        return false;
    }
    let range = crate::StoryRange::new("body", candidate.start, candidate.start);
    let receipt = crate::Receipt {
        new_para_ids: Vec::new(), revision_ids: Vec::new(),
        range: Some(crate::LocRange {
            start: crate::Loc::new("body", &candidate.paragraph, candidate.offset),
            end: crate::Loc::new("body", &candidate.paragraph, candidate.offset + units),
        }),
    };
    self.record_resident_text_edit(&range, Some(&candidate.text), true, prepared.before,
        true, true, prepared.length, Some(candidate.attributes.clone()), false,
        prepared.measurement_patch, &receipt);
    self.typing_epoch.set(None);
    self.typing_preserves_seeds.set(false);
    self.render.borrow().stories.get("body").is_some_and(|lowered| lowered.local.edit.is_some())
}

